package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;
import java.util.concurrent.TimeUnit;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

class HttpPaymentGatewayTest {

    private MockWebServer provider;
    private HttpPaymentGateway sut;

    @BeforeEach
    void startProvider() throws Exception {
        provider = new MockWebServer();
        provider.start();
        sut = new HttpPaymentGateway(RestClient.builder().baseUrl(provider.url("/").toString()).build());
    }

    @AfterEach
    void stopProvider() throws Exception {
        provider.shutdown();
    }

    private static MockResponse json(int status, String body) {
        return new MockResponse().setResponseCode(status).setHeader("Content-Type", "application/json").setBody(body);
    }

    @Test
    void sends_the_reference_amount_and_currency_as_json_to_the_authorizations_endpoint() throws Exception {
        provider.enqueue(json(200, "{\"status\":\"approved\"}"));

        sut.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        RecordedRequest request = provider.takeRequest(5, TimeUnit.SECONDS);
        assertThat(request.getMethod()).isEqualTo("POST");
        assertThat(request.getPath()).isEqualTo("/v1/authorizations");
        assertThat(request.getHeader("Content-Type")).startsWith("application/json");
        JsonNode body = new ObjectMapper().readTree(request.getBody().readUtf8());
        assertThat(body.size()).isEqualTo(3);
        assertThat(body.get("reference").asText()).isEqualTo("ORD-7");
        assertThat(body.get("amount").decimalValue()).isEqualByComparingTo("12.50");
        assertThat(body.get("currency").asText()).isEqualTo("EUR");
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        provider.enqueue(json(200, "{\"status\":\"approved\"}"));

        assertThat(sut.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR"))).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        provider.enqueue(json(200, "{\"status\":\"declined\"}"));

        assertThat(sut.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR"))).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void additional_fields_in_the_answer_are_tolerated() {
        provider.enqueue(json(200, "{\"status\":\"approved\",\"id\":\"auth_1\",\"risk\":{\"score\":3}}"));

        assertThat(sut.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR"))).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_402_refusal_is_a_declined_outcome_whatever_the_body() {
        provider.enqueue(json(402, "{\"error\":\"card_refused\"}"));

        assertThat(sut.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR"))).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_without_a_body_is_a_declined_outcome() {
        provider.enqueue(new MockResponse().setResponseCode(402));

        assertThat(sut.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR"))).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_request_the_provider_rejects_is_reported_as_a_failure() {
        provider.enqueue(json(400, "{\"error\":\"invalid_currency\"}"));

        assertThatThrownBy(() -> sut.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_as_a_decline() {
        provider.enqueue(new MockResponse().setResponseCode(503));

        assertThatThrownBy(() -> sut.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }
}
